		set("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		set("rdf4j.lmdb.janinoCodegen.wildcardPredicates", "true");
		// The query must require the wildcard-predicate producer; node-predicate projection would be a different route.
		set(LmdbNativeKernelIr.NODE_PREDICATES_PROPERTY, "false");
		set(LmdbNativeKernelLowering.SCAN_SOURCES_PROPERTY, "true");
		set("rdf4j.lmdb.wcoj.enabled", "false");
